/* swtrees_witness.c -- variant of swtrees.c: prints the FIRST tree whose certified category is >= TARGET
 * (0: s=1, 1: single, 2: double, 3: triple, 4: random) and exits. Usage: ./swtrees_witness n target
 * swtrees.c -- Implementation B (C): exhaustive exact check of the switching
 * conjecture for main eigenvalues on all trees with n vertices.
 *
 * For each free tree T (generated by the Wright-Richmond-Odlyzko-McKay
 * level-sequence algorithm, as in networkx.nonisomorphic_trees) we
 *   1. compute the characteristic polynomial phi(x) EXACTLY (int64) as the
 *      matching polynomial of T (phi(T)=sum_k (-1)^k m_k x^{n-2k});
 *   2. compute g = gcd(phi, phi') over Q, CERTIFIED: g is the monic gcd mod a
 *      61-bit prime, lifted symmetrically, and accepted only if g divides phi
 *      and phi' exactly over Z (__int128); then deg g >= deg gcd_Q >= deg g_p
 *      = deg g, so d := n - deg g is exactly the number of distinct eigenvalues;
 *   3. search s in {+-1}^n (s=1, single flips, double flips, triple flips,
 *      then exhaustive) until rank_{F_p}[s, As, ..., A^{d-1}s] = d.
 *      Since rank_Q >= rank_{F_p} and rank_Q <= d always, this CERTIFIES that
 *      every distinct eigenvalue of T^s is main.
 * Output per n: #trees, #certified, histogram of the kind of s found.
 * Usage: ./swtrees n [modulus_index residue]   (optional sharding)
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAXN 32
typedef long long ll;
typedef unsigned long long ull;
typedef __int128 i128;

static const ull P61 = 2305843009213693951ULL; /* 2^61-1 */
static const ull PR[3] = {2305843009213693951ULL, 4611686018427387847ULL, 1152921504606846883ULL};
static ull PMOD;

static inline ull mulm(ull a, ull b){ return (ull)(((unsigned __int128)a*b)%PMOD); }
static inline ull addm(ull a, ull b){ ull c=a+b; if(c>=PMOD) c-=PMOD; return c; }
static inline ull subm(ull a, ull b){ return a>=b? a-b : a+PMOD-b; }
static ull powm(ull a, ull e){ ull r=1; while(e){ if(e&1) r=mulm(r,a); a=mulm(a,a); e>>=1;} return r; }
static inline ull invm(ull a){ return powm(a, PMOD-2); }
static inline ull tom(ll x){ ll m=(ll)(x % (ll)PMOD); if(m<0) m+=PMOD; return (ull)m; }

static int n;
static int L[MAXN];           /* level sequence */
static int par[MAXN];
static int adj[MAXN][MAXN], deg_[MAXN];

/* ---------- WROM generator (port of networkx) ---------- */
static int next_rooted_tree(int *pred, int len, int p){
  if(p<0){ p=len-1; while(pred[p]==1) p--; }
  if(p==0) return 0;
  int q=p-1; while(pred[q]!=pred[p]-1) q--;
  for(int i=p;i<len;i++) pred[i]=pred[i-p+q];
  return 1;
}
static void split_tree(const int *lay, int len, int *left, int *nl, int *rest, int *nr){
  int one=0, m=-1;
  for(int i=0;i<len;i++){ if(lay[i]==1){ if(one){ m=i; break;} else one=1; } }
  if(m<0) m=len;
  *nl=0; for(int i=1;i<m;i++) left[(*nl)++]=lay[i]-1;
  *nr=0; rest[(*nr)++]=0; for(int i=m;i<len;i++) rest[(*nr)++]=lay[i];
}
static int maxv(const int *a,int k){ int m=a[0]; for(int i=1;i<k;i++) if(a[i]>m) m=a[i]; return m; }
/* returns 1 and modifies cand if a next tree exists, 0 if exhausted */
static int next_tree(int *cand, int len){
  int left[MAXN], rest[MAXN], nl, nr;
  split_tree(cand,len,left,&nl,rest,&nr);
  int lh=maxv(left,nl), rh=maxv(rest,nr);
  int valid = rh>=lh;
  if(valid && rh==lh){
    if(nl>nr) valid=0;
    else if(nl==nr){ /* lexicographic compare left > rest */
      int cmp=0; for(int i=0;i<nl;i++){ if(left[i]!=rest[i]){ cmp = left[i]>rest[i]?1:-1; break;} }
      if(cmp>0) valid=0;
    }
  }
  if(valid) return 1;
  int p=nl;
  int old_p_val = cand[p];
  if(!next_rooted_tree(cand,len,p)) return 0; /* networkx would crash here; never happens */
  if(old_p_val>2){
    int l2[MAXN], r2[MAXN], nl2, nr2;
    split_tree(cand,len,l2,&nl2,r2,&nr2);
    int nlh=maxv(l2,nl2);
    int k=nlh+1; /* suffix 1..nlh+1 */
    for(int i=0;i<k;i++) cand[len-k+i]=i+1;
  }
  return 1; /* as in networkx: the jumped-to candidate is yielded directly */
}
static void layout_to_graph(const int *lay, int len){
  int stack[MAXN], sp=0;
  memset(deg_,0,sizeof(deg_));
  for(int i=0;i<len;i++){
    if(sp){
      int j=stack[sp-1];
      while(lay[j]>=lay[i]){ sp--; j=stack[sp-1]; }
      adj[i][deg_[i]++]=j; adj[j][deg_[j]++]=i; par[i]=j;
    } else par[i]=-1;
    stack[sp++]=i;
  }
}

/* ---------- exact characteristic polynomial via matching polynomial ---------- */
/* phi[k] = coefficient of x^k, k=0..n */
static ll M0[MAXN][MAXN/2+2], M1[MAXN][MAXN/2+2];
static int order_[MAXN];
static void charpoly(ll *phi){
  /* root at 0; process vertices in reverse BFS order */
  int q[MAXN], qh=0, qt=0, seen[MAXN]={0}, pr[MAXN];
  q[qt++]=0; seen[0]=1; pr[0]=-1;
  while(qh<qt){ int v=q[qh++]; for(int i=0;i<deg_[v];i++){ int w=adj[v][i]; if(!seen[w]){ seen[w]=1; pr[w]=v; q[qt++]=w; } } }
  int H=n/2+1;
  for(int idx=n-1;idx>=0;idx--){
    int v=q[idx];
    ll A0[MAXN/2+2]={0}, A1[MAXN/2+2]={0}; A0[0]=1; /* A0: v unmatched so far; A1: v matched */
    for(int i=0;i<deg_[v];i++){ int c=adj[v][i]; if(c==pr[v]) continue;
      ll T[MAXN/2+2]; for(int k=0;k<H;k++) T[k]=M0[c][k]+M1[c][k];
      ll N0[MAXN/2+2]={0}, N1[MAXN/2+2]={0};
      for(int a=0;a<H;a++) if(A0[a]) for(int b=0;a+b<H;b++){ N0[a+b]+=A0[a]*T[b]; if(a+b+1<H) N1[a+b+1]+=A0[a]*M0[c][b]; }
      for(int a=0;a<H;a++) if(A1[a]) for(int b=0;a+b<H;b++) N1[a+b]+=A1[a]*T[b];
      memcpy(A0,N0,sizeof(A0)); memcpy(A1,N1,sizeof(A1));
    }
    memcpy(M0[v],A0,sizeof(A0)); memcpy(M1[v],A1,sizeof(A1));
  }
  for(int k=0;k<=n;k++) phi[k]=0;
  for(int k=0;k<H && 2*k<=n;k++){ ll mk=M0[0][k]+M1[0][k]; phi[n-2*k] = (k&1)? -mk : mk; }
}

/* ---------- polynomial gcd mod p, and certified lift ---------- */
static int pdeg(const ull *a, int da){ while(da>=0 && a[da]==0) da--; return da; }
static int gcd_modp(const ull *a0, int da, const ull *b0, int db, ull *g){
  ull a[MAXN+1], b[MAXN+1]; memcpy(a,a0,sizeof(ull)*(da+1)); memcpy(b,b0,sizeof(ull)*(db+1));
  da=pdeg(a,da); db=pdeg(b,db);
  while(db>=0){
    /* a = a mod b */
    ull ib=invm(b[db]);
    while(da>=db){ ull f=mulm(a[da],ib); int sh=da-db; for(int i=0;i<=db;i++) a[i+sh]=subm(a[i+sh],mulm(f,b[i])); da=pdeg(a,da-1); if(da<0) break; }
    /* swap */
    ull t[MAXN+1]; int dt;
    memcpy(t,a,sizeof(ull)*(MAXN+1)); dt=da;
    memcpy(a,b,sizeof(ull)*(MAXN+1)); da=db;
    memcpy(b,t,sizeof(ull)*(MAXN+1)); db=dt;
  }
  ull ia=invm(a[da]); for(int i=0;i<=da;i++) g[i]=mulm(a[i],ia);
  return da;
}
/* exact division check over Z: does monic g (deg dg) divide f (deg df)? */
static int divides_exact(const ll *g, int dg, const ll *f, int df){
  i128 r[MAXN+1]; for(int i=0;i<=df;i++) r[i]=f[i];
  for(int j=0;j<=dg;j++){ if(g[j]>((ll)1<<50) || g[j]< -((ll)1<<50)) return 0; }
  for(int i=df;i>=dg;i--){ i128 c=r[i]; if(c==0) continue; if(c>((i128)1<<60) || c< -((i128)1<<60)) return 0; for(int j=0;j<=dg;j++) r[i-dg+j]-=c*(i128)g[j]; }
  for(int i=0;i<dg;i++) if(r[i]!=0) return 0;
  return 1;
}

/* ---------- Krylov rank mod PK = 2^31-1 (64-bit arithmetic) ---------- */
static const ull PK = 2147483647ULL;
static ull invk(ull a){ ull r=1, e=PK-2; a%=PK; while(e){ if(e&1) r=r*a%PK; a=a*a%PK; e>>=1;} return r; }
static int krylov_rank(const int *s, int d){
  /* rows = vectors A^j s, j=0..d-1, n columns; rank over F_PK.
     rank_{F_PK} <= rank_Q <= d, so rank == d certifies that s is good. */
  static ull M[MAXN][MAXN];
  ull v[MAXN], w[MAXN];
  for(int i=0;i<n;i++) v[i]= s[i]>0?1:PK-1;
  for(int j=0;j<d;j++){
    for(int i=0;i<n;i++) M[j][i]=v[i];
    for(int i=0;i<n;i++){ ull acc=0; for(int k=0;k<deg_[i];k++) acc+=v[adj[i][k]]; w[i]=acc%PK; }
    memcpy(v,w,sizeof(ull)*n);
  }
  int rank=0;
  for(int col=0; col<n && rank<d; col++){
    int piv=-1; for(int r=rank;r<d;r++) if(M[r][col]){ piv=r; break; }
    if(piv<0) continue;
    if(piv!=rank){ for(int c=0;c<n;c++){ ull t=M[piv][c]; M[piv][c]=M[rank][c]; M[rank][c]=t; } }
    ull ip=invk(M[rank][col]);
    for(int r=rank+1;r<d;r++) if(M[r][col]){ ull f=M[r][col]*ip%PK; for(int c=col;c<n;c++){ M[r][c]=(M[r][c] + (PK - f*M[rank][c]%PK))%PK; } }
    rank++;
  }
  return rank;
}

int main(int argc, char **argv){
  n=atoi(argv[1]);
  int target = atoi(argv[2]); int shard_m = 1, shard_r = 0;
  PMOD=P61;
  /* initial layout: range(n//2+1) + range(1,(n+1)//2) */
  int len=0; for(int i=0;i<=n/2;i++) L[len++]=i; for(int i=1;i<(n+1)/2;i++) L[len++]=i;
  /* networkx 3.4: the initial layout is fed directly to next_tree */
  ll ntrees=0, ncert=0, nfail=0, hist[6]={0}; /* 0: s=1, 1: single flip, 2: double, 3: triple, 4: random or exhaustive, 5: gcd-cert failure */
  ll dhist[MAXN+1]={0};
  ll count_all=0;
  while(1){
    int r=next_tree(L,len);
    if(r==0) break;
    /* valid tree */
    count_all++;
    if((count_all % shard_m)==shard_r){
      ntrees++;
      layout_to_graph(L,len);
      ll phi[MAXN+1], dphi[MAXN+1];
      charpoly(phi);
      for(int k=0;k<n;k++) dphi[k]=(k+1)*phi[k+1];
      /* certified gcd */
      int dg=-1; ll g[MAXN+1]; int ok=0;
      for(int pi=0;pi<3 && !ok;pi++){
        PMOD=PR[pi];
        ull a[MAXN+1], b[MAXN+1], gp[MAXN+1];
        for(int k=0;k<=n;k++) a[k]=tom(phi[k]);
        for(int k=0;k<n;k++) b[k]=tom(dphi[k]);
        dg=gcd_modp(a,n,b,n-1,gp);
        for(int k=0;k<=dg;k++){ ull x=gp[k]; g[k]= (x> PMOD/2)? -(ll)(PMOD-x) : (ll)x; }
        if(divides_exact(g,dg,phi,n) && divides_exact(g,dg,dphi,n-1)) ok=1;
      }
      PMOD=P61;
      if(!ok){ hist[5]++; nfail++; goto next; }
      {
      int d=n-dg; dhist[d]++;
      int s[MAXN]; int found=-1;
      for(int i=0;i<n;i++) s[i]=1;
      if(krylov_rank(s,d)==d) found=0;
      for(int u=0;u<n && found<0;u++){ s[u]=-1; if(krylov_rank(s,d)==d) found=1; s[u]=1; }
      for(int u=0;u<n && found<0;u++) for(int v=u+1;v<n && found<0;v++){ s[u]=-1; s[v]=-1; if(krylov_rank(s,d)==d) found=2; s[u]=1; s[v]=1; }
      for(int u=0;u<n && found<0;u++) for(int v=u+1;v<n && found<0;v++) for(int w=v+1;w<n && found<0;w++){ s[u]=s[v]=s[w]=-1; if(krylov_rank(s,d)==d) found=3; s[u]=s[v]=s[w]=1; }
      if(found<0){ /* random s (xorshift64), counted in the 'exhaustive' bucket as found=4 */
        static ull xs=88172645463325252ULL;
        for(int tries=0; tries<20000 && found<0; tries++){
          for(int i=0;i<n;i++){ xs^=xs<<13; xs^=xs>>7; xs^=xs<<17; s[i]=(xs>>33)&1? -1:1; }
          if(krylov_rank(s,d)==d) found=4;
        }
        for(int i=0;i<n;i++) s[i]=1;
      }
      if(found<0){
        for(ull mask=0; mask < (1ULL<<(n-1)) && found<0; mask++){ for(int i=0;i<n;i++) s[i]= (i<n-1 && ((mask>>i)&1))? -1:1; if(krylov_rank(s,d)==d) found=4; }
      }
      if(found<0){ nfail++; printf("FAIL tree level seq:"); for(int i=0;i<len;i++) printf(" %d",L[i]); printf("\n"); fflush(stdout); }
      else { ncert++; hist[found]++;
        if(found>=target){ printf("WITNESS n=%d category=%d level seq:",n,found); for(int i=0;i<len;i++) printf(" %d",L[i]); printf("\n"); return 0; } }
      }
    }
    next:
    if(!next_rooted_tree(L,len,-1)) break;
  }
  printf("n=%d shard=%d/%d trees=%lld certified=%lld fail=%lld | s=1:%lld single:%lld double:%lld triple:%lld random/exh:%lld gcdfail:%lld | total_enumerated=%lld\n",
    n,shard_r,shard_m,ntrees,ncert,nfail,hist[0],hist[1],hist[2],hist[3],hist[4],hist[5],count_all);
  printf("d-histogram:"); for(int d=0;d<=n;d++) if(dhist[d]) printf(" %d:%lld",d,dhist[d]); printf("\n");
  return 0;
}
